import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.XVqh0tHf.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),s={name:"09-interview-qa.md"};function i(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-the-architecture-of-the-vitals-healthcare-platform" tabindex="-1">Q1: Can you walk me through the architecture of the VITALS Healthcare platform? <a class="header-anchor" href="#q1-can-you-walk-me-through-the-architecture-of-the-vitals-healthcare-platform" aria-label="Permalink to &quot;Q1: Can you walk me through the architecture of the VITALS Healthcare platform?&quot;">​</a></h3><p><strong>Answer</strong>: VITALS is a full-stack smart hospital operating system built on Express 5, Node.js, and MongoDB with Mongoose. The backend is structured into 14 modular route controllers covering patient intake, longitudinal treatment plans, clinical decision support (CDSS), document/DICOM metadata storage, and ward occupancy. We implement multi-tenancy at the data layer, secure our endpoints using a dual-layer JWT and session-based RBAC system with brute-force lockout defenses in <code>securityService.js</code>, and provide client-side portals for visual bed allocation, upfront bill estimation, and Jitsi-based telehealth.</p><h3 id="q2-why-did-you-choose-express-5-over-express-4" tabindex="-1">Q2: Why did you choose Express 5 over Express 4? <a class="header-anchor" href="#q2-why-did-you-choose-express-5-over-express-4" aria-label="Permalink to &quot;Q2: Why did you choose Express 5 over Express 4?&quot;">​</a></h3><p><strong>Answer</strong>: Express 5 natively supports asynchronous route handlers and middleware returning Promises. In Express 4, unhandled Promise rejections inside async route handlers would either crash the Node process or require repetitive <code>try/catch</code> blocks calling <code>next(err)</code>. Express 5 automatically routes rejected promises directly to our centralized <code>errorHandler.js</code>, making clinical API code cleaner and far less error-prone.</p><h3 id="q3-how-does-the-clinical-decision-support-system-prevent-medical-errors" tabindex="-1">Q3: How does the Clinical Decision Support System prevent medical errors? <a class="header-anchor" href="#q3-how-does-the-clinical-decision-support-system-prevent-medical-errors" aria-label="Permalink to &quot;Q3: How does the Clinical Decision Support System prevent medical errors?&quot;">​</a></h3><p><strong>Answer</strong>: When a doctor prescribes a medication in <code>decisionSupportRoutes.js</code>, the service cross-references the proposed substance against <code>ContraindicationRule.js</code> and the patient&#39;s recorded drug allergies in MongoDB. If an adverse drug interaction or known allergy is identified, the system halts the order with a &#39;CRITICAL&#39; severity alert and clinical justification, preventing adverse drug events before orders reach the hospital pharmacy.</p><h3 id="q4-how-is-patient-medical-data-isolated-across-multiple-hospital-branches" tabindex="-1">Q4: How is patient medical data isolated across multiple hospital branches? <a class="header-anchor" href="#q4-how-is-patient-medical-data-isolated-across-multiple-hospital-branches" aria-label="Permalink to &quot;Q4: How is patient medical data isolated across multiple hospital branches?&quot;">​</a></h3><p><strong>Answer</strong>: All clinical models enforce a required <code>tenantId</code> field. Every database query in our services layer strictly scopes documents to the authenticated user&#39;s tenant ID, ensuring that clinicians at Hospital Branch A cannot view or manipulate patient records belonging to Hospital Branch B.</p><h3 id="q5-how-do-you-handle-high-concurrency-bed-allocation-without-double-booking" tabindex="-1">Q5: How do you handle high-concurrency bed allocation without double-booking? <a class="header-anchor" href="#q5-how-do-you-handle-high-concurrency-bed-allocation-without-double-booking" aria-label="Permalink to &quot;Q5: How do you handle high-concurrency bed allocation without double-booking?&quot;">​</a></h3><p><strong>Answer</strong>: We use atomic MongoDB update operations (<code>findOneAndUpdate</code>) with optimistic concurrency checks. When a bed is reserved, the query verifies that the bed&#39;s state is currently &#39;Available&#39; during the update operation. If two nurses click the same bed simultaneously, the first write succeeds and the second fails with a 409 Conflict, alerting the user to select an alternate bed.</p>',12)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
